create or replace function public.enforce_article_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  is_editor boolean := public.is_editor();
  is_writer boolean := (select auth.uid());
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.author_id is distinct from old.author_id
     or new.status is distinct from old.status
     or new.body is distinct from old.body
     or new.title is distinct from old.title
  then
    if old.status = 'published' then
      raise exception 'Published articles cannot be changed';
    end if;

    if new.status = 'draft' then
      raise exception 'Drafts can only be created by writers, not edited';
    end if;

    if NOT is_editor and old.author_id <> current_user then
      raise exception 'Only the writer or an editor may change this article';
    end if;

    if is_editor and old.status not in ('in_review', 'draft') then
      raise exception 'Only in_review articles may be edited by editors';
    end if;

    if is_writer then
      if new.status = 'published' or new.status = 'in_review' then
        raise exception 'Writers cannot publish or submit for review';
      end if;
      if old.status in ('in_review', 'published') then
        raise exception 'Writers cannot edit articles already submitted';
      end if;
    end if;

    if is_editor and old.status = 'draft' then
      raise exception 'Editors cannot change drafts';
    end if;

    if is_writer and new.status in ('in_review', 'published') then
      raise exception 'Writers cannot transition to in_review or published';
    end if;

    if not is_editor and old.status = 'in_review' then
      raise exception 'Only editors may change articles in review';
    end if;
  end if;

  return new;
end;
$$;

create trigger enforce_article_change
before update on public.articles
for each row
execute function public.enforce_article_change();

