create function private.can_read_medical_records(p_patient_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.care_team ct
    where ct.patient_id = p_patient_id and ct.clinician_id = auth.uid()
  )
  or exists (
    select 1 from public.break_glass_grants g
    where g.patient_id = p_patient_id
      and g.clinician_id = auth.uid()
      and g.expires_at > now()
  )
$$;

create function private.break_glass(p_patient_id bigint, p_reason text) returns timestamptz
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_result timestamptz;
begin
  if v_uid is null then
    raise exception 'not authenticated'
      using errcode = '42501';
  end if;

  if not exists (select 1 from public.clinicians c where c.user_id = v_uid) then
    raise exception 'only clinicians can break the glass'
      using errcode = '42501';
  end if;

  if p_reason is null or trim(p_reason) = '' or char_length(trim(p_reason)) < 10 then
    raise exception 'reason must be at least 10 characters'
      using errcode = '42501';
  end if;

  if not exists (select 1 from public.patients p where p.id = p_patient_id) then
    raise exception 'patient not found'
      using errcode = '42501';
  end if;

  insert into public.break_glass_grants (patient_id, clinician_id, reason, expires_at)
  values (p_patient_id, v_uid, p_reason, now() + interval '1 hour')
  returning expires_at into v_result;

  return v_result;
end
$$;

